package com.nexus.access.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import org.junit.jupiter.api.Test; import com.nexus.access.backend.user.User;
class JwtServiceTest { @Test void createsSignedTokenWithoutSensitiveClaims(){User user=new User();user.setEmail("jwt@example.com");user.setRole("USER"); try{var id=User.class.getDeclaredField("id");id.setAccessible(true);id.set(user,java.util.UUID.randomUUID());}catch(Exception e){throw new RuntimeException(e);} JwtService service=new JwtService("this-is-a-test-secret-with-at-least-thirty-two-chars",900);var claims=service.parse(service.create(user));assertEquals("jwt@example.com",claims.get("email"));assertFalse(claims.containsKey("passwordHash"));assertTrue(claims.getExpiration().after(claims.getIssuedAt()));}}
